begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions;
select no_plan();
insert into auth.users(id) values ('19000000-0000-0000-0000-000000000001'), ('19000000-0000-0000-0000-000000000002'), ('19000000-0000-0000-0000-000000000003');
insert into public.members(id, auth_user_id, username, full_name_en, system_role)
values ('29000000-0000-0000-0000-000000000001', '19000000-0000-0000-0000-000000000001', 'audit_owner', 'Audit Owner', 'OWNER');
insert into public.members(id, auth_user_id, username, full_name_en, must_change_password)
values ('29000000-0000-0000-0000-000000000003', '19000000-0000-0000-0000-000000000002', 'audit_member', 'Audit Member', true);

create function public.test_fail_member_audit() returns trigger language plpgsql as $$
begin
  if current_setting('test.fail_member_audit', true) = 'yes' and new.entity = 'member' then raise exception 'TEST_AUDIT_FAILED'; end if;
  return new;
end $$;
create trigger test_member_audit_failure before insert on public.audit_log for each row execute function public.test_fail_member_audit();

set local role authenticated;
select set_config('request.jwt.claim.sub', '19000000-0000-0000-0000-000000000001', true);
select throws_ok($$select public.member_admin_write(gen_random_uuid(), '19000000-0000-0000-0000-000000000001', 'create', gen_random_uuid(), '{}')$$, '42501', null, 'even owner clients cannot call service adapter');
select throws_ok($$select public.member_admin_begin(gen_random_uuid(), '19000000-0000-0000-0000-000000000001', gen_random_uuid(), 'create')$$, '42501', null, 'clients cannot create Auth intents');
select throws_ok($$select public.member_admin_finish(gen_random_uuid(), 'SUCCEEDED')$$, '42501', null, 'clients cannot mark Auth operations successful');
select throws_ok($$select * from public.member_admin_operations$$, '42501', null, 'operation ledger is private');
reset role;
set local role service_role;
select throws_ok($$select public.member_admin_write(gen_random_uuid(), '19000000-0000-0000-0000-000000000002', 'create', gen_random_uuid(), '{}')$$, 'P0001', 'FORBIDDEN', 'adapter requires active owner actor');
select throws_ok($$select public.member_admin_write(gen_random_uuid(), '19000000-0000-0000-0000-000000000001', 'create', gen_random_uuid(), '{"password":"must never persist"}')$$, 'P0001', 'INVALID_MEMBER', 'adapter rejects credentials');
select set_config('test.fail_member_audit', 'yes', true);
select throws_ok($$select public.member_admin_write('89000000-0000-0000-0000-000000000001', '19000000-0000-0000-0000-000000000001', 'create', '29000000-0000-0000-0000-000000000002', '{"username":"audit_guide","full_name_en":"Guide"}')$$, 'P0001', 'TEST_AUDIT_FAILED', 'failed audit aborts create');
reset role;
select is((select count(*) from public.members where username = 'audit_guide'), 0::bigint, 'failed audited create leaves no member');
select is((select count(*) from public.client_ops where op_id = '89000000-0000-0000-0000-000000000001'), 0::bigint, 'failed audited create leaves no receipt');
select set_config('test.fail_member_audit', 'no', true);
set local role service_role;
select public.member_admin_write('89000000-0000-0000-0000-000000000001', '19000000-0000-0000-0000-000000000001', 'create', '29000000-0000-0000-0000-000000000002', '{"username":"audit_guide","full_name_en":"Guide"}');
select throws_ok($$select public.member_admin_write('89000000-0000-0000-0000-000000000001', '19000000-0000-0000-0000-000000000001', 'create', '29000000-0000-0000-0000-000000000002', '{"username":"audit_guide","full_name_en":"Changed replay"}')$$, 'P0001', 'OP_ID_CONFLICT', 'replay is bound to the exact whitelisted payload');
select public.member_admin_write('89000000-0000-0000-0000-000000000001', '19000000-0000-0000-0000-000000000001', 'create', '29000000-0000-0000-0000-000000000002', '{"username":"audit_guide","full_name_en":"Guide"}');
reset role;
select is((select count(*) from public.audit_log where entity_id = '29000000-0000-0000-0000-000000000002' and action = 'MEMBER_CREATED'), 1::bigint, 'create and replay emit one audit');
select set_config('test.fail_member_audit', 'yes', true);
set local role service_role;
select throws_ok($$select public.member_admin_write(gen_random_uuid(), '19000000-0000-0000-0000-000000000001', 'update', '29000000-0000-0000-0000-000000000002', '{"full_name_en":"Changed"}')$$, 'P0001', 'TEST_AUDIT_FAILED', 'failed audit aborts edit');
select throws_ok($$select public.member_admin_write(gen_random_uuid(), '19000000-0000-0000-0000-000000000001', 'deactivate', '29000000-0000-0000-0000-000000000002')$$, 'P0001', 'TEST_AUDIT_FAILED', 'failed audit aborts deactivation');
select throws_ok($$select public.member_admin_write(gen_random_uuid(), '19000000-0000-0000-0000-000000000001', 'link', '29000000-0000-0000-0000-000000000002', '{"auth_user_id":"19000000-0000-0000-0000-000000000003"}')$$, 'P0001', 'TEST_AUDIT_FAILED', 'failed audit aborts Auth link');
reset role;
select is((select full_name_en from public.members where username = 'audit_guide'), 'Guide', 'failed edit rolled back');
select is((select is_active from public.members where username = 'audit_guide'), true, 'failed deactivation rolled back');
select is((select auth_user_id from public.members where username = 'audit_guide'), null::uuid, 'failed link rolled back');
set local role service_role;
select throws_ok($$select public.member_admin_begin('89000000-0000-0000-0000-000000000002', '19000000-0000-0000-0000-000000000001', '29000000-0000-0000-0000-000000000002', 'set_password')$$, 'P0001', 'TEST_AUDIT_FAILED', 'intent and preflight audit are atomic');
reset role;
select is((select count(*) from public.member_admin_operations where member_id = '29000000-0000-0000-0000-000000000002'), 0::bigint, 'failed preflight leaves no intent');
select set_config('test.fail_member_audit', 'no', true);
set local role service_role;
select public.member_admin_begin('89000000-0000-0000-0000-000000000002', '19000000-0000-0000-0000-000000000001', '29000000-0000-0000-0000-000000000002', 'set_password');
select is(public.member_admin_begin(gen_random_uuid(), '19000000-0000-0000-0000-000000000001', '29000000-0000-0000-0000-000000000002', 'deactivate')->>'status', 'NEEDS_REVIEW', 'pending intent blocks another external mutation');
select set_config('test.fail_member_audit', 'yes', true);
select throws_ok($$select public.member_admin_finish('89000000-0000-0000-0000-000000000002', 'SUCCEEDED')$$, 'P0001', 'TEST_AUDIT_FAILED', 'completion audit failure aborts status transition');
reset role;
select is((select status from public.member_admin_operations where id = '89000000-0000-0000-0000-000000000002'), 'STARTED', 'durable pending intent remains for reconciliation');
select is((select count(*) from public.audit_log where entity_id = '29000000-0000-0000-0000-000000000002' and action = 'MEMBER_PASSWORD_SET'), 0::bigint, 'intent does not falsely claim password success');
select set_config('test.fail_member_audit', 'no', true);
set local role service_role;
select public.member_admin_finish('89000000-0000-0000-0000-000000000002', 'NEEDS_REVIEW', '19000000-0000-0000-0000-000000000002', 'AUTH_USER_LINK_FAILED');
select public.member_admin_finish('89000000-0000-0000-0000-000000000002', 'SUCCEEDED', '19000000-0000-0000-0000-000000000002', 'OPERATOR_VERIFIED');
select public.member_admin_finish('89000000-0000-0000-0000-000000000002', 'SUCCEEDED');
select public.member_admin_write(gen_random_uuid(), '19000000-0000-0000-0000-000000000001', 'deactivate', '29000000-0000-0000-0000-000000000002');
select throws_ok($$select public.member_admin_begin(gen_random_uuid(), '19000000-0000-0000-0000-000000000002', '29000000-0000-0000-0000-000000000002', 'change_own_password')$$, 'P0001', 'FORBIDDEN', 'member cannot change another account password');
select set_config('test.fail_member_audit', 'yes', true);
select throws_ok($$select public.member_admin_begin('89000000-0000-0000-0000-000000000003', '19000000-0000-0000-0000-000000000002', '29000000-0000-0000-0000-000000000003', 'change_own_password')$$, 'P0001', 'TEST_AUDIT_FAILED', 'self password intent and audit are atomic');
reset role;
select is((select count(*) from public.member_admin_operations where id = '89000000-0000-0000-0000-000000000003'), 0::bigint, 'failed self password audit leaves no intent');
select is((select must_change_password from public.members where id = '29000000-0000-0000-0000-000000000003'), true, 'failed self password intent preserves forced-change flag');
select set_config('test.fail_member_audit', 'no', true);
set local role service_role;
select public.member_admin_begin('89000000-0000-0000-0000-000000000003', '19000000-0000-0000-0000-000000000002', '29000000-0000-0000-0000-000000000003', 'change_own_password');
select set_config('test.fail_member_audit', 'yes', true);
select throws_ok($$select public.member_admin_finish('89000000-0000-0000-0000-000000000003', 'SUCCEEDED', '19000000-0000-0000-0000-000000000002')$$, 'P0001', 'TEST_AUDIT_FAILED', 'failed self password completion rolls back the flag');
reset role;
select is((select status from public.member_admin_operations where id = '89000000-0000-0000-0000-000000000003'), 'STARTED', 'failed self password completion remains recoverable');
select is((select must_change_password from public.members where id = '29000000-0000-0000-0000-000000000003'), true, 'failed self password audit preserves forced-change flag');
select set_config('test.fail_member_audit', 'no', true);
set local role service_role;
select public.member_admin_finish('89000000-0000-0000-0000-000000000003', 'SUCCEEDED', '19000000-0000-0000-0000-000000000002');
reset role;
select is((select must_change_password from public.members where id = '29000000-0000-0000-0000-000000000003'), false, 'successful self password change clears the forced-change flag');
select is((select count(*) from public.audit_log where entity_id = '29000000-0000-0000-0000-000000000003' and action = 'MEMBER_PASSWORD_CHANGED'), 1::bigint, 'self password completion is audited');
select set_config('test.fail_member_audit', 'yes', true);
select throws_ok($$select public.member_admin_write(gen_random_uuid(), '19000000-0000-0000-0000-000000000001', 'reactivate', '29000000-0000-0000-0000-000000000002')$$, 'P0001', 'TEST_AUDIT_FAILED', 'failed audit aborts reactivation');
reset role;
select is((select is_active from public.members where username = 'audit_guide'), false, 'failed reactivation rolled back');
select is((select count(*) from public.audit_log where entity_id = '29000000-0000-0000-0000-000000000002' and action = 'MEMBER_PASSWORD_SET'), 1::bigint, 'verified completion records one password audit');
select is((select status from public.member_admin_operations where id = '89000000-0000-0000-0000-000000000002'), 'SUCCEEDED', 'reconciliation marks completed intent');
select * from finish();
rollback;
